{"command": "zcat /tmp/sglang_profile/profile_batch1_input8192_output2048_decode.trace.json.gz | /opt/venv/bin/python3 -c "
import json, sys
data = json.load(sys.stdin)
if 'traceEvents' in data:
    events = data['traceEvents']
    kernel_times = {}
    for e in events:
        if e.get('ph') == 'X' and 'dur' in e:
            name = e.get('name', 'unknown')
            dur_us = e['dur']  # duration in microseconds
            if 'kernel' in name.lower() or 'fused' in name.lower() or 'gemm' in name.lower() or 'moe' in name.lower() or 'attn' in name.lower():
                kernel_times[name] = kernel_times.get(name, 0) + dur_us
    total = sum(kernel_times.values())
    sorted_kernels = sorted(kernel_times.items(), key=lambda x: -x[1])[:15]
    print(f'Total kernel time: {total/1000:.2f}ms')
    print()
    for name, time_us in sorted_kernels:
        pct = (time_us / total) * 100 if total > 0 else 0
        print(f'{pct:5.1f}% {time_us/1000:7.2f}ms  {name}')
" 2>&1 | head -30
"}

